# AI steps 3+4 — Settings › AI & Connections (master switch), launcher, ` shortcut, Private flag, and the AI panel
# flow (questions → parts list → plan → solver check → Apply) with the scripted test provider.
from playwright.sync_api import sync_playwright
import os, sys; sys.stdout.reconfigure(encoding='utf-8'); S=os.environ.get('HYDRA_ROOT', os.path.abspath(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..' if os.path.basename(os.path.dirname(os.path.abspath(__file__)))=='tests' else '../..')))
R=[]
def check(n,c,x=''): R.append(('PASS' if c else 'FAIL',n,str(x)[:300]))
with sync_playwright() as p:
    b=p.chromium.launch(); pg=b.new_page(viewport={'width':1440,'height':900})
    errs=[]; pg.on('pageerror',lambda e: errs.append(str(e)))
    url='file://'+S+'/dist/HYDRA/HYDRA.html'; pg.goto(url); pg.wait_for_timeout(2500)
    ev=pg.evaluate; H="window.HYDRA.S"; A="window.HYDRA.ai"; q=pg.query_selector
    w=lambda ms=200: pg.wait_for_timeout(ms)
    def comps(): return ev(f"(()=>{{const s=Object.values({H}.project.value.circuits).find(c=>c.name==='Clamp'); return s?s.components.length:-1}})()")
    # ---- off by default ----
    check('AI off by default: no launcher', q('.ailaunch') is None and not ev(f"{A}.settings.aiSettings.value.enabled"))
    pg.keyboard.press('Backquote'); w(); check('` does nothing while AI is off', q('.aipanel') is None)
    r=ev(f"{A}.call('get_project_info',{{}},{{source:'mcp'}})"); check('outside AI refused while off', not r['ok'], r)
    ev(f"{H}.openModal('prefs',{{tab:'ai'}})"); w(300)
    check('Settings has AI & Connections, master unchecked, rest hidden', q('.aiset') is not None and not ev("document.querySelector('.aiset-master input').checked") and q('.aiset h4') is None)
    pg.click('.aiset-master input'); w()
    check('master on shows the sections', len(pg.query_selector_all('.aiset h4'))==3)
    check('browser build: connections need HYDRA.exe', 'needs the desktop app' in ev("document.querySelector('.aiset').textContent"))
    check('locked rules shown as locked switches', ev("[...document.querySelectorAll('.aiset-row input[disabled]')].map(i=>i.checked).join()")=='true,false')
    pg.click('footer button.primary'); w(300)
    check('saved: launcher in the title bar, not connected', q('.titlebar .ailaunch.none') is not None)
    check('only overrides stored', ev(f"JSON.stringify({A}.settings.overridesOf({A}.settings.aiSettings.value))")=='{"enabled":true}')
    pg.reload(); pg.wait_for_timeout(2500)
    check('setting survives a restart', ev(f"{A}.settings.aiSettings.value.enabled") and q('.ailaunch') is not None)
    pg.click('.ailaunch'); w(300); check('launcher (not connected) opens Connect an AI', 'Connect an AI' in ev("document.querySelector('.modal header')?.textContent||''") and 'needs the desktop app' in ev("document.querySelector('.modal').textContent")); pg.keyboard.press('Escape'); w()
    # ---- test provider, panel, backtick ----
    ev(f"{A}.useDemoProvider()"); w(); check('connected: green status', q('.ailaunch.ready') is not None)
    pg.keyboard.press('Backquote'); w(); check('` opens the panel', q('.aipanel.float') is not None)
    pg.keyboard.press('Backquote'); w(); check('` closes it', q('.aipanel') is None)
    ev(f"(()=>{{const X=window.HYDRA; X.Pj.setProject(X.Pj.newProjectData({{name:'AI panel',template:'blank',unitSystem:'SI-bar'}}),{{dirty:true}}); X.S.addNode('sheet', null, 'hydraulic', 'Clamp');}})()")
    nid=ev(f"Object.values({H}.project.value.nodes).find(n=>n.type==='sheet').id"); ev(f"{H}.openSheetTab('{nid}')"); w(800)
    pg.click('.ailaunch'); w()
    check('panel: modes, context chip, sends line', ev("[...document.querySelectorAll('.aimodes button')].map(b=>b.textContent).join('|')")=='Build|Ask|Fix errors|PLC logic' and 'Clamp · hydraulic' in ev("document.querySelector('.aichips').textContent") and 'circuit JSON only' in ev("document.querySelector('.aichips').textContent"))
    pg.fill('.aicomp textarea','Make a clamping circuit: clamp first, then press'); pg.keyboard.press('Enter'); w(400)
    check('user message + question form', q('.aimsg.user') is not None and q('.aicard .aiq') is not None and len(pg.query_selector_all('.aiq .aidecide'))==5)
    pg.click('.aiq .aidecide:nth-of-type(3) input') if False else ev("document.querySelectorAll('.aiq .aidecide input')[2].click()"); w()
    check('Let AI decide greys the field', ev("document.querySelectorAll('.aiq input.in')[2].disabled"))
    pg.click('.aicard .aibtns button.primary'); w(400)
    rows=ev("[...document.querySelectorAll('.aibom tbody tr')].map(r=>r.cells[0].textContent)")
    check('parts list with 9 rows', rows==['1A1','1V1','1P1','1M1','1V2','1Z1','1Z2','1Z3','1Z4'], rows)
    check('mandatory parts locked', ev("[...document.querySelectorAll('.aibom tbody tr')].filter(r=>r.querySelector('svg') && !r.querySelector('button')).length")==4)
    check('assumptions show what AI decided', 'AI decided: stroke' in ev("document.querySelector('.aibom').parentElement.textContent"))
    pg.click('button[aria-label="Remove 1Z4"]'); w(); check('row removed', len(pg.query_selector_all('.aibom tbody tr'))==8)
    h0=ev(f"{H}.histVer.value")
    pg.click('text=Approve & build'); w(900)
    check('plan card: ready, command list', q('.aicard.plan.ready') is not None and 'add_component h_cyl_double 1A1' in ev("document.querySelector('.aicmds').textContent"))
    check('ghost on the canvas', len(pg.query_selector_all('.dcanvas .ai-ghost-part'))==8)
    check('solver check passed shown', 'Solver check passed' in ev("document.querySelector('.aisim').textContent"), ev("document.querySelector('.aisim')?.textContent"))
    check('launcher amber: plan waiting', q('.ailaunch.apply') is not None)
    check('nothing applied yet', comps()==0 and ev(f"{H}.histVer.value")==h0)
    pg.click('text=Apply to sheet'); w(400)
    check('Apply: 8 parts, one undo step, card says Applied', comps()==8 and ev(f"{H}.histVer.value")==h0+1 and ev("document.querySelector('.aicard.plan .aict').textContent")=='Applied')
    check('ghost gone, launcher green again', len(pg.query_selector_all('.ai-ghost-part'))==0 and q('.ailaunch.ready') is not None)
    # ---- other modes, errors ----
    pg.click('.aimodes button:nth-child(2)'); pg.fill('.aicomp textarea','what is on the sheet?'); pg.keyboard.press('Enter'); w(300)
    check('Ask mode answers from the sheet', 'Clamp has 8 parts and 6 nets.' in ev("[...document.querySelectorAll('.aimsg.ai')].map(m=>m.textContent).join('|')"))
    pg.click('.aimodes button:nth-child(3)'); pg.fill('.aicomp textarea','check it'); pg.keyboard.press('Enter'); w(300)
    check('Fix errors mode runs the rule check', 'No problems found.' in ev("[...document.querySelectorAll('.aimsg.ai')].map(m=>m.textContent).join('|')"))
    ev(f"(async()=>{{const s={A}.session; await s.send({{mode:'build',approvedBom:[{{tag:'1A1',part:'x',rating:'x'}}]}});}})()"); w(400)
    check('a failing plan shows an error in the thread', 'already used' in ev("[...document.querySelectorAll('.aimsg.err')].map(m=>m.textContent).join('|')"))
    # ---- pin into the right dock, AI log ----
    pg.click('.aihead button[aria-label="Pin"]'); w(300)
    check('pinned: AI tab in the right dock', q('.aipanel.float') is None and q('.aibody.docked') is not None and ev("[...document.querySelectorAll('.panel .dtabs button')].some(b=>b.textContent==='AI' && b.classList.contains('on'))"))
    pg.click('.aibody.docked .aihead button[aria-label="Pin"]'); w(300); check('unpinned: floating again', q('.aipanel.float') is not None)
    ev("window.HYDRA.designer.st.dock.value={open:true,tab:'ailog'}"); w(300)
    check('AI log tab in the bottom dock', ev("[...document.querySelectorAll('.ddock .dtabs button')].some(b=>b.textContent==='AI log')") and len(pg.query_selector_all('.ddock .ailog tbody tr'))>3 and q('.ddock .aitag') is not None)
    # ---- Private ----
    ev(f"{H}.openModal('projectProps')"); w(300); pg.click('.modal .checkrow input'); pg.click('.modal footer button.primary'); w(300)
    check('Private checkbox sets the flag', ev(f"{H}.project.value.manifest.private")==True)
    pg.click('.aimodes button:nth-child(2)'); pg.fill('.aicomp textarea','anything'); pg.keyboard.press('Enter'); w(300)
    check('Private project: the AI is refused', 'Private' in ev("[...document.querySelectorAll('.aimsg.err')].map(m=>m.textContent).join('|')"))
    check('Private project: arguments not logged', ev(f"{A}.aiLog.value.at(-1).args")=='(Private project — not logged)', ev(f"{A}.aiLog.value.at(-1)"))
    # ---- master switch off again ----
    ev(f"{A}.settings.saveAiSettings({{...{A}.settings.aiSettings.value, enabled:false}})"); w(300)
    check('master off: launcher, panel and AI log tab gone', q('.ailaunch') is None and q('.aipanel') is None and q('.aibody') is None and not ev("[...document.querySelectorAll('.ddock .dtabs button')].some(b=>b.textContent==='AI log')"))
    check('no page errors', not errs, errs)
    b.close()
for r in R: print(*r)
print(sum(1 for r in R if r[0]=='PASS'),'/',len(R))
